create or replace function public.save_health_record(p_payload jsonb,p_expected bigint) returns setof public.health_records language plpgsql security invoker set search_path='' as $$ begin if auth.uid() is null then raise exception 'Authentication required' using errcode='28000'; end if; if p_expected=0 then return query insert into public.health_records(user_id,payload,revision) values(auth.uid(),p_payload,1) returning *; else return query update public.health_records set payload=p_payload,revision=revision+1,updated_at=now() where user_id=auth.uid() and revision=p_expected returning *; if not found then raise exception 'revision_conflict: Newer cloud record exists' using errcode='PT409'; end if; end if; end $$;
